<script setup lang="ts">
import { computed, shallowRef } from 'vue'
import type { CharacterEdge } from '../types/characterGraph'
import type { OnlineNode } from '../types/onlineNetwork'
import CharacterPortrait from './CharacterPortrait.vue'
import PortraitPreview from './PortraitPreview.vue'
import EntityNames from './EntityNames.vue'
import { matchesEntityName } from '../utils/entityNames'
const props = defineProps<{ nodes: OnlineNode[]; edges: CharacterEdge[]; selectedId: string | null; selectedEdgeId: string | null }>()
const emit = defineEmits<{ selectNode: [id: string]; selectEdge: [id: string] }>()
const search = shallowRef('')
const filtered = computed(() => props.nodes.filter(node => matchesEntityName(node, search.value, node.roles)))
const selected = computed(() => props.nodes.find(node => node.id === props.selectedId))
const edge = computed(() => props.edges.find(item => item.id === props.selectedEdgeId))
const related = computed(() => props.edges.filter(item => item.source === props.selectedId || item.target === props.selectedId))
const name = (id: string) => props.nodes.find(node => node.id === id)?.label || id
</script>
<template>
  <aside class="online-inspector">
    <section v-if="edge" class="selection-detail" aria-live="polite"><p class="detail-caption">关系详情</p><h3>{{ name(edge.source) }} {{ edge.directed ? '→' : '—' }} {{ name(edge.target) }}</h3><strong class="edge-name">{{ edge.label }}</strong><span v-if="edge.spoiler" class="edge-status">剧透</span><span v-if="edge.ended" class="edge-status">已结束</span><p v-if="edge.directed">{{ name(edge.source) }}{{ edge.target.startsWith('position:') ? '担任' : `是${name(edge.target)}的` }}{{ edge.label }}。</p><p v-if="edge.description">{{ edge.description }}</p><small>{{ edge.evidence }}</small><a :href="edge.sourceUrl || undefined" target="_blank" rel="noopener noreferrer">核对 Bangumi 来源</a></section>
    <section v-else-if="selected" class="selection-detail" aria-live="polite"><div class="selected-title"><CharacterPortrait :node="selected" large/><div><h3>{{ selected.label }}</h3><small>{{ selected.originalName !== selected.label ? selected.originalName : selected.role }}</small></div></div><EntityNames :node="selected"/><PortraitPreview :node="selected"/><p>{{ selected.description }}</p><p v-if="selected.roles.length" class="roles">{{ selected.roles.join(' / ') }}</p><a :href="selected.sourceUrl" target="_blank" rel="noopener noreferrer">查看 Bangumi 档案</a><h4>当前作品内的关系</h4><div class="related-list"><button v-for="item in related" :key="item.id" @click="emit('selectEdge', item.id)"><span>{{ name(item.source) }} {{ item.directed ? '→' : '—' }} {{ name(item.target) }}</span><strong>{{ item.label }}</strong></button></div><p v-if="!related.length" class="muted">当前筛选下，来源未提供与本作其他节点的关系。</p></section>
    <section v-else class="selection-detail hint"><h3>点击节点，改变探索中心</h3><p>连线上的文字就是关系。点击连线可查看方向、备注和原始出处。</p></section>
    <section class="online-index"><label>查找节点 <small>{{ nodes.length }}</small><input v-model="search" type="search" placeholder="中文名、原名、别名或职务"></label><div class="index-scroll"><button v-for="node in filtered" :key="node.id" :aria-pressed="selectedId === node.id" :aria-label="`以${node.label}为中心`" @click="emit('selectNode', node.id)"><CharacterPortrait :node="node"/><span><strong>{{ node.label }}</strong><small>{{ node.role }}</small></span></button><p v-if="!filtered.length" class="muted">没有匹配的节点。</p></div></section>
  </aside>
</template>
<style scoped>
