nspector{display:grid;grid-template-columns:1fr 1fr;border-left:0;border-top:1px solid #dfe7e1}.selection-detail{border-bottom:0;border-right:1px solid #e3eae5}.index-scroll{max-height:240px}}@media(max-width:520px){.online-inspector{grid-template-columns:1fr}.selection-detail{border-right:0;border-bottom:1px solid #e3eae5}}
